-- MySQL 8.0.16+ required for enforced CHECK constraints. Apply explicitly after
-- backup/review; never at server startup. All objects use the ayambil_ prefix.
CREATE TABLE ayambil_schema_version (version INT PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_settings (id TINYINT PRIMARY KEY CHECK(id=1), registration_open BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO ayambil_settings VALUES (1,FALSE);
CREATE TABLE ayambil_admins (id CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(256) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_admin_sessions (token_hash CHAR(64) PRIMARY KEY, admin_id CHAR(36) NOT NULL, csrf_hash CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, FOREIGN KEY(admin_id) REFERENCES ayambil_admins(id), INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_events (event_date CHAR(10) PRIMARY KEY CHECK(event_date IN ('2026-11-02','2026-11-03')), snapshot JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
-- Approved snapshots are loaded separately by the reviewed seed procedure.
CREATE TABLE ayambil_bookings (id CHAR(36) PRIMARY KEY, number VARCHAR(64) NOT NULL UNIQUE, contact_name VARCHAR(120) NOT NULL, mobile VARCHAR(20) NOT NULL, event_date CHAR(10) NOT NULL, status ENUM('active','cancelled') NOT NULL DEFAULT 'active', whatsapp_consent BOOLEAN NOT NULL CHECK(whatsapp_consent=TRUE), terms_version VARCHAR(24) NOT NULL, terms_accepted_at DATETIME(3) NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(event_date) REFERENCES ayambil_events(event_date), UNIQUE(id,event_date), INDEX(event_date,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_idempotency (key_hash CHAR(64) PRIMARY KEY, payload_hash CHAR(64) NOT NULL, booking_id CHAR(36) NULL UNIQUE, FOREIGN KEY(booking_id) REFERENCES ayambil_bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_attendees (id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, full_name VARCHAR(120) NOT NULL, ordinal TINYINT NOT NULL CHECK(ordinal BETWEEN 1 AND 2), status ENUM('active','cancelled') NOT NULL DEFAULT 'active', FOREIGN KEY(booking_id) REFERENCES ayambil_bookings(id), UNIQUE(booking_id,ordinal), UNIQUE(id,booking_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_registrations (attendee_id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, event_date CHAR(10) NOT NULL, FOREIGN KEY(attendee_id,booking_id) REFERENCES ayambil_attendees(id,booking_id), FOREIGN KEY(booking_id,event_date) REFERENCES ayambil_bookings(id,event_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_passes (id CHAR(36) PRIMARY KEY, attendee_id CHAR(36) NOT NULL, number VARCHAR(64) NOT NULL UNIQUE, snapshot JSON NOT NULL, revision INT NOT NULL, status ENUM('active','cancelled','superseded') NOT NULL DEFAULT 'active', current_attendee CHAR(36) GENERATED ALWAYS AS (IF(status='superseded',NULL,RTRIM(attendee_id))) STORED, FOREIGN KEY(attendee_id) REFERENCES ayambil_attendees(id), UNIQUE(current_attendee), UNIQUE(attendee_id,revision)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_capabilities (key_hash CHAR(64) PRIMARY KEY, pass_id CHAR(36) NOT NULL UNIQUE, expires_at DATETIME(3) NOT NULL, revoked_at DATETIME(3) NULL, FOREIGN KEY(pass_id) REFERENCES ayambil_passes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_audit (id CHAR(36) PRIMARY KEY, admin_id CHAR(36) NOT NULL, booking_id CHAR(36) NOT NULL, action VARCHAR(24) NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(admin_id) REFERENCES ayambil_admins(id), FOREIGN KEY(booking_id) REFERENCES ayambil_bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_whatsapp_attempts (id CHAR(36) PRIMARY KEY, booking_id CHAR(36) NOT NULL, status ENUM('disabled') NOT NULL DEFAULT 'disabled', created_at DATETIME(3) NOT NULL, FOREIGN KEY(booking_id) REFERENCES ayambil_bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE ayambil_rate_limits (bucket CHAR(64) PRIMARY KEY, window_start BIGINT NOT NULL, attempts INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO ayambil_schema_version(version) VALUES(1);


